
(()=>{
const root=document.getElementById('atlas-options');
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const assets={map:'assets/map.jpg',station:'assets/station.jpg',street:'assets/street.jpg',plan:'assets/plan.jpg',bridge:'assets/bridge.jpg',junction:'assets/junction.jpg',network:'assets/network.jpg'};
let ideas=[
 {title:'A better arrival',type:'Rapid transit · picture',img:'station',x:.34,y:.27,desc:'A station interior shows the experience of arriving. Keep its image readable while a tether identifies the approximate location.'},
 {title:'A street for people',type:'Streets & places · picture',img:'street',x:.37,y:.36,desc:'A street-level render belongs to a place, but has no meaningful map scale. Give it a stable reading size.'},
 {title:'Reconnect the junction',type:'Cycling & walking · plan',img:'plan',x:.49,y:.47,desc:'A plan can be opened over its approximate area. This screenshot is illustrative and has not been georeferenced.'},
 {title:'Around the eastern bays',type:'Buses & ferries · report map',img:'network',x:.69,y:.57,desc:'A report map has its own labels and orientation. Keep the original readable; do not imply it precisely fits the ground.'},
 {title:'A place by the water',type:'Streets & places · picture',img:'bridge',x:.63,y:.37,desc:'A perspective render gives a sense of place. An anchor is more honest than stretching it across the streets.'},
 {title:'A safer connection',type:'Cycling & walking · plan',img:'junction',x:.52,y:.7,desc:'A local drawing can be positioned approximately. Only one plan unfolds at once, keeping nearby ideas visible.'}
];
const proposals={cards:['Anchored postcards','Images keep a readable screen size. Tethers carry the geography; nearby ideas become one browsable stack.'],fold:['Fold-out plans','Browse small plan covers, then unfold one drawing over its footprint. Other ideas stay folded.'],compare:['Compare on the ground','Slide between the drawing and the streets. Keep the full original available when alignment is only approximate.'],edit:['Place the image first','Drop an image, drag it into place, then adjust its size and angle. Drag the image or use position controls. Save to try it in all three prototypes.']};
let saved={}; try {saved=JSON.parse(localStorage.getItem('atlas-placement')||'{}'); const stored=JSON.parse(localStorage.getItem('atlas-ideas')||'null'); if(stored)ideas=stored;} catch(error) {console.warn('Saved prototype data could not be loaded',error);}
root.querySelectorAll('.atlas-app').forEach(app=>{
 const mode=app.dataset.mode,editing=mode==='edit'; let editIndex=2; let zoom=1,pan={x:0,y:0},selected=mode==='compare'?2:null,unfold=mode==='compare',slide=55,stack=0,custom=null,place={x:.5,y:.43,size:250,angle:-15};
 if(editing&&saved.place)place={...place,...saved.place};
 app.innerHTML=`<header class="atlas-head"><div><div class="brand">Atlas Tāmaki<span style="color:var(--accent)">.</span></div><div class="eyebrow">Auckland could be more</div></div><div class="stamp">DESIGN EXPLORATION<br>Interactive HTML prototype</div></header><div class="atlas-map" aria-label="Auckland map prototype"><img class="basemap" alt="Crop of Auckland street basemap from the supplied Felt screenshot"><svg class="wires" aria-hidden="true"></svg><div class="map-items"></div><div class="map-tools"><button class="overview">${editing?'Reset placement':'Overview'}</button>${mode==='cards'?'<button class="stack-next">Nearby ideas · 1 / 2</button>':''}<span class="spacer"></span><div class="zoom"><button aria-label="Zoom out">−</button><button aria-label="Zoom in">+</button></div></div><div class="detail" hidden aria-live="polite"></div><div class="map-label">Illustrative placement · Basemap from your Felt screenshot</div></div><footer class="atlas-bottom"><div><h3>${proposals[mode][0]}</h3><p>${proposals[mode][1]}</p></div><span class="count">${editing?'Saved in this browser':'6 sample ideas'}</span></footer><section class="source-sheet" hidden aria-label="Image and source"></section>`;
 const map=app.querySelector('.atlas-map'),base=app.querySelector('.basemap'),items=app.querySelector('.map-items'),wires=app.querySelector('.wires'),detail=app.querySelector('.detail'),sheet=app.querySelector('.source-sheet');base.src=assets.map;
 function remember(){try{localStorage.setItem('atlas-placement',JSON.stringify({place}));}catch{}}
 function xy(x,y){return {x:map.clientWidth/2+(x-.5)*1024*scale()+pan.x,y:map.clientHeight/2+(y-.5)*720*scale()+pan.y};}
 function scale(){return Math.max(map.clientWidth/1024,map.clientHeight/720)*zoom;}
 function showSource(i){const d=ideas[i];sheet.innerHTML=`<header><h3>${escapeHtml(d.title)}</h3><button>Back to map</button></header><img src="${assets[d.img]||d.img}" alt="Source image crop for ${escapeHtml(d.title)}"><p>${d.desc}</p><p><strong>Source & credit</strong><br>${d.credit?escapeHtml(d.credit)+"<br>":""}Example cropped from the screenshots you supplied of Better Public Transport in Auckland on Felt. Original author and reuse permission are unverified. Captions here are prototype copy.</p><a href="https://felt.com/map/Better-Public-Transport-in-Auckland-zVsTZyUzQICmR9BS5SiwixD?share=1" target="_blank" rel="noreferrer">Open the reference Felt map ↗</a>`;sheet.hidden=false;sheet.querySelector('button').onclick=()=>{sheet.hidden=true;detail.querySelector('button')?.focus();};sheet.querySelector('button').focus();}
 function details(){if(selected===null||editing){detail.hidden=true;return;}const d=ideas[selected];detail.hidden=false;detail.innerHTML=`<div class="detail-top"><div><h3>${escapeHtml(d.title)}</h3><span style="font-size:10px;color:var(--quiet)">${d.type} · approximate location</span></div><button class="close" aria-label="Close idea">×</button></div><p>${d.desc}</p><div class="detail-actions">${mode!=='cards'?`<button class="toggle solid">${unfold?'Fold drawing':'Open on map'}</button>`:''}<button class="source">Image, detail & source ↗</button></div>`;detail.querySelector('.close').onclick=()=>{selected=null;unfold=false;render();};detail.querySelector('.source').onclick=()=>showSource(selected);const toggle=detail.querySelector('.toggle');if(toggle)toggle.onclick=()=>{unfold=!unfold;render();};}
 function select(i){selected=i;unfold=mode==='compare';render();remember();}
 function render(){const w=map.clientWidth,h=map.clientHeight,s=scale();base.style.cssText=`width:${1024*s}px;height:${720*s}px;left:${w/2-512*s+pan.x}px;top:${h/2-360*s+pan.y}px`;items.innerHTML='';wires.innerHTML='';
  if(editing){drawEditor();return;}
  if(mode==='cards'){
   const narrow=w<600,indices=narrow?[stack*3,stack*3+1,stack*3+2]:[stack,stack?3:2,4,5];
   const spots=narrow?[[12,90],[w-138,225],[12,370]]:[[24,96],[w-184,100],[24,320],[w-184,315]];
   indices.forEach((i,j)=>{const d=ideas[i],a=xy(d.x,d.y),[cx,cy]=spots[j],cw=narrow?126:160;wires.innerHTML+=`<path d="M ${a.x} ${a.y} L ${cx+cw/2} ${cy+55}" fill="none" stroke="#527564" stroke-width="1.5"/><circle cx="${a.x}" cy="${a.y}" r="5" fill="#205d49" stroke="#fffefa" stroke-width="2"/>`;const b=document.createElement('button');b.className='postcard'+(i===selected?' selected':'');b.style.cssText=`left:${cx}px;top:${cy}px`;b.innerHTML=`<img src="${assets[d.img]||d.img}" alt=""><strong>${escapeHtml(d.title)}</strong><small>${d.type.split(' · ')[0]}</small>`;b.onclick=()=>select(i);items.append(b);});
  }else{
   ideas.forEach((d,i)=>{const p=xy(d.x,d.y);if(i===2||i===5){const f=document.createElement('div');f.className='footprint';f.style.cssText=`left:${p.x}px;top:${p.y}px;width:${(i===2?270:150)*s}px;height:${(i===2?180:120)*s}px`;items.append(f);}
    if(selected===i&&unfold){const img=document.createElement('img');img.src=assets[d.img]||d.img;img.alt='Approximate placement of sample drawing';img.className='ground-plan';img.style.cssText=`left:${p.x}px;top:${p.y}px;width:${(d.size||(mode==='compare'?450:340))*s}px`;img.style.transform=`translate(-50%,-50%) rotate(${d.angle??-15}deg)`;if(mode==='compare'){img.style.transform='translate(-50%,-50%)';img.style.clipPath=`inset(0 ${100-slide}% 0 0)`;}items.append(img);}
    const b=document.createElement('button');b.className=(i===2||i===5||i===3)?'fold-tag':'pin';b.style.cssText=`left:${Math.max(35,Math.min(w-50,p.x))}px;top:${Math.max(155,Math.min(h-210,p.y))}px`;b.innerHTML=b.className==='pin'?String(i+1):`<img src="${assets[d.img]||d.img}" alt=""><span>${escapeHtml(d.title)}</span>`;b.setAttribute('aria-label',d.title);if(selected===i&&unfold)b.style.display='none';b.onclick=()=>select(i);items.append(b);
   });
  }
  const compare=app.querySelector('.compare-control');if(compare)compare.hidden=!(unfold&&selected!==null);const divider=app.querySelector('.divider');if(divider){divider.hidden=!(unfold&&selected!==null);const a=xy(ideas[selected??2].x,ideas[selected??2].y);divider.style.left=`${a.x+(slide/100-.5)*450*s}px`;}
  details();
 }
 app.querySelector('.overview').onclick=()=>{zoom=1;pan={x:0,y:0};if(editing){place={x:.5,y:.43,size:250,angle:-15};app.querySelector('[name=size]').value=250;app.querySelector('[name=angle]').value=-15;}render();};
 app.querySelectorAll('.zoom button').forEach((b,i)=>b.onclick=()=>{zoom=Math.max(.8,Math.min(2,zoom+(i?.2:-.2)));render();});
 const next=app.querySelector('.stack-next');if(next)next.onclick=()=>{stack=1-stack;selected=null;next.textContent=`Nearby ideas · ${stack+1} / 2`;render();};
 if(mode==='compare'){const c=document.createElement('div');c.className='compare-control';c.innerHTML='<label for="atlas-swipe"><span>Drawing</span><span>Street map</span></label><input id="atlas-swipe" aria-label="Reveal drawing" type="range" min="0" max="100" value="55">';map.append(c);const d=document.createElement('div');d.className='divider';map.append(d);c.querySelector('input').oninput=e=>{slide=+e.target.value;render();};}
 if(editing){map.insertAdjacentHTML('beforeend',`<label class="upload">Replace image<input type="file" accept="image/*" aria-label="Choose image"></label><div class="editor-tools"><label>Image size<input name="size" type="range" min="90" max="500" value="${place.size}"></label><label>Rotation<input name="angle" type="range" min="-90" max="90" value="${place.angle}"></label><label>Display as<select name="kind"><option value="plan">Plan on the ground</option><option value="picture">Anchored picture</option></select></label><label>Caption<input name="caption" value="Reconnect the junction"></label><label>Credit / source<input name="credit" placeholder="Author and source URL"></label><button class="solid save">Save idea</button></div><div class="saved" hidden aria-live="polite"></div>`);
  map.querySelector('.upload').insertAdjacentHTML('afterbegin','<label>Edit idea<select class="idea-select">'+ideas.map((d,i)=>'<option value="'+i+'">'+escapeHtml(d.title)+'</option>').join('')+'</select></label>');
  const chooser=app.querySelector('.idea-select');chooser.value=editIndex;chooser.onchange=()=>{editIndex=+chooser.value;const d=ideas[editIndex];custom=null;place={x:d.x,y:d.y,size:d.size||250,angle:d.angle??-15};app.querySelector('[name=caption]').value=d.title;app.querySelector('[name=credit]').value=d.credit||'';app.querySelector('[name=size]').value=place.size;app.querySelector('[name=angle]').value=place.angle;render();};
  app.querySelector('.editor-tools').insertAdjacentHTML('beforeend','<label>East / west<input name="east" aria-label="East west position" type="range" min="0" max="100" value="50"></label><label>North / south<input name="north" aria-label="North south position" type="range" min="0" max="100" value="43"></label><button class="export">Export ideas JSON</button>');
  app.querySelector('[name=east]').oninput=e=>{place.x=+e.target.value/100;render();};app.querySelector('[name=north]').oninput=e=>{place.y=+e.target.value/100;render();};
  app.querySelector('.export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(ideas,null,2)],{type:'application/json'}));a.download='atlas-ideas.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
  app.querySelector('[type=file]').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.size>2500000){alert('Choose an image smaller than 2.5 MB for this browser-local prototype.');return;}const r=new FileReader();r.onload=()=>{custom=r.result;render();};r.readAsDataURL(file);};
  ['size','angle'].forEach(key=>app.querySelector(`[name=${key}]`).oninput=e=>{place[key]=+e.target.value;render();});app.querySelector('[name=kind]').onchange=render;
  app.querySelector('.save').onclick=()=>{const note=app.querySelector('.saved');note.hidden=false;const d=ideas[editIndex];d.title=app.querySelector('[name=caption]').value.trim()||'Untitled idea';d.credit=app.querySelector('[name=credit]').value;d.x=place.x;d.y=place.y;d.size=place.size;d.angle=place.angle;if(custom)d.img=custom;try{localStorage.setItem('atlas-ideas',JSON.stringify(ideas));note.textContent='Saved. Open any prototype to see this idea.';}catch{note.textContent='Could not save: browser storage is full or unavailable. Export JSON to keep your changes.';}remember();};
 }
 function drawEditor(){const p=xy(place.x,place.y),picture=app.querySelector('[name=kind]')?.value==='picture';const image=document.createElement('img');image.className='editor-image';image.alt='Draggable image placement preview';image.draggable=false;image.src=custom||assets[ideas[editIndex].img]||ideas[editIndex].img;image.style.cssText=`left:${p.x}px;top:${p.y}px;width:${picture?180:place.size*scale()}px;transform:translate(-50%,-50%) rotate(${picture?0:place.angle}deg)`;items.append(image);}
 let drag=null;map.addEventListener('pointerdown',e=>{if(e.target.closest('button,input,select,a,.detail,.editor-tools,.upload'))return;const isImage=e.target.classList.contains('editor-image');drag={x:e.clientX,y:e.clientY,pan:{...pan},place:{...place},image:isImage};map.setPointerCapture(e.pointerId);});map.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(drag.image){place.x=drag.place.x+dx/(1024*scale());place.y=drag.place.y+dy/(720*scale());}else pan={x:drag.pan.x+dx,y:drag.pan.y+dy};render();});map.addEventListener('pointerup',()=>{if(drag)remember();drag=null;});map.addEventListener('pointercancel',()=>drag=null);
 new ResizeObserver(render).observe(map);render();
});
})();
